export function getReadingsByLevel(level: EnglishLevel): ReadingPractical[] {
  return readingPracticals.filter((r) => r.level === level);
}

export function getReadingById(id: string): ReadingPractical | undefined {
  return readingPracticals.find((r) => r.id === id);
}
